diff --git a/src/alg.cpp b/src/alg.cpp
index 17b7a59..232b2a6 100644
--- a/src/alg.cpp
+++ b/src/alg.cpp
@@ -1,26 +1,503 @@
 #include "query_core.h"
 #include <vector>
 #include <cmath>
-// Runnable exhaustive starter: numeric bucket order, no adaptive termination.
-// Replace this with an efficient query-local implementation.
-class ExhaustiveCore : public QueryCore {
-    int l=0, k=0, cursor=0;
-    std::vector<double> projection;
+#include <cstdint>
+#include <cstring>
+#include <atomic>
+#include <mutex>
+#include <string>
+#include <limits>
+#include <fcntl.h>
+#include <sys/mman.h>
+#include <sys/stat.h>
+#include <unistd.h>
+
+// FARGO global multi-probing (paper Sections 3.2.2-3.2.3, 4.2, Algorithm 1).
+//
+// Probe order: all buckets of all tables by ascending squared quantization
+// distance (Eq. 11-12), ties by table.  Per table the K flip costs are sorted
+// and split into a low half (indices < h) and a high half; a bucket's QD is
+// low_sum + high_sum, each half summed in ascending index order.  The first
+// probes come from a small shift/expand heap; deeper probing switches to
+// threshold batches over the sorted half-subset lists X (low) and Y (high),
+// whose rows X[i] + Y[j] are already sorted.  Both phases evaluate the same
+// floating-point expression, so the handoff threshold is exact.
+//
+// Termination (Eq. 16): with I_k the kth result and U the partition bound,
+// stop when I_k >= cU, otherwise when 1 - phi(d; acos(I_k / cU))^L < 0.1 with
+// theta rounded up and d rounded down on the calibration grid.  For fixed
+// (I_k, c, U) the rule is a cutoff on d, cached until the inputs change.
+
+namespace {
+
+const double kPTau = 0.1;
+const double kInf = std::numeric_limits<double>::infinity();
+
+inline bool rule_holds(double phi, int L) {
+    double alpha1 = 1.0 - phi;
+    double alpha2 = 1.0 - std::pow(1.0 - alpha1, (double)L);
+    return alpha2 < kPTau;
+}
+
+// Immutable calibration resource, mapped once per path.  Per-row cutoff
+// columns are derived lazily from the file; they depend only on it and L.
+struct Calibration {
+    std::string path;
+    bool ok = false;
+    int K = 0, rows = 0, cols = 0;
+    double theta_step = 0, score_step = 0;
+    const char* cdf = nullptr;   // rows*cols doubles at file offset 36 (unaligned)
+    std::vector<char> owned;
+    std::mutex mu;
+
+    double at(int r, int j) const {
+        double v;
+        std::memcpy(&v, cdf + ((size_t)r * cols + j) * 8, 8);
+        return v;
+    }
+    std::vector<std::pair<int, std::atomic<int>*> > cutoffs;
+
+    // First column where the rule holds when it holds on a suffix of a
+    // nondecreasing row; cols when it never holds; -2 for irregular rows.
+    int cutoff(std::atomic<int>* cache, int r, int L) {
+        int v = cache[r].load(std::memory_order_relaxed);
+        if (v != -1) return v;
+        bool monotone = true;
+        double prev = at(r, 0);
+        for (int j = 1; j < cols && monotone; ++j) {
+            const double x = at(r, j);
+            monotone = x >= prev;
+            prev = x;
+        }
+        if (monotone) {
+            int lo = 0, hi = cols;
+            while (lo < hi) {
+                int mid = (lo + hi) >> 1;
+                if (rule_holds(at(r, mid), L)) hi = mid; else lo = mid + 1;
+            }
+            v = lo;
+        } else {
+            v = -2;
+        }
+        cache[r].store(v, std::memory_order_relaxed);
+        return v;
+    }
+
+    std::atomic<int>* cutoffs_for(int L) {
+        std::lock_guard<std::mutex> g(mu);
+        for (size_t i = 0; i < cutoffs.size(); ++i)
+            if (cutoffs[i].first == L) return cutoffs[i].second;
+        std::atomic<int>* a = new std::atomic<int>[rows];
+        for (int r = 0; r < rows; ++r) a[r].store(-1, std::memory_order_relaxed);
+        cutoffs.push_back(std::make_pair(L, a));
+        return a;
+    }
+
+    void load() {
+        int fd = ::open(path.c_str(), O_RDONLY);
+        if (fd < 0) return;
+        struct stat st;
+        if (fstat(fd, &st) != 0 || st.st_size < 36) { ::close(fd); return; }
+        size_t size = (size_t)st.st_size;
+        const char* base = nullptr;
+        void* m = mmap(nullptr, size, PROT_READ, MAP_PRIVATE, fd, 0);
+        if (m != MAP_FAILED) {
+            base = (const char*)m;
+        } else {
+            owned.resize(size);
+            size_t got = 0;
+            while (got < size) {
+                ssize_t n = ::pread(fd, &owned[got], size - got, (off_t)got);
+                if (n <= 0) break;
+                got += (size_t)n;
+            }
+            if (got != size) { ::close(fd); return; }
+            base = owned.data();
+        }
+        ::close(fd);
+        if (std::memcmp(base, "FARGOSQ1", 8) != 0) return;
+        int32_t h[3];
+        std::memcpy(h, base + 8, 12);
+        std::memcpy(&theta_step, base + 20, 8);
+        std::memcpy(&score_step, base + 28, 8);
+        K = h[0]; rows = h[1]; cols = h[2];
+        if (rows <= 0 || cols <= 0 || !(theta_step > 0) || !(score_step > 0)) return;
+        if ((size - 36) / 8 < (size_t)rows * (size_t)cols) return;
+        cdf = base + 36;
+        ok = true;
+    }
+};
+
+Calibration* calibration(const char* path) {
+    static std::mutex mu;
+    static std::vector<Calibration*> all;
+    std::lock_guard<std::mutex> g(mu);
+    for (size_t i = 0; i < all.size(); ++i)
+        if (all[i]->path == path) return all[i];
+    Calibration* c = new Calibration();
+    c->path = path;
+    c->load();
+    all.push_back(c);
+    return c;
+}
+
+const long long kHeapProbes = 128;   // probes served by the heap phase
+
+class FargoCore : public QueryCore {
 public:
-    void reset(int L,int K,const double* p) override {
-        l=L; k=K; cursor=0; projection.assign(p,p+L*K);
+    FargoCore() {}
+
+    void reset(int L_, int K_, const double* p) override {
+        L = L_; K = K_;
+        proj.assign(p, p + (size_t)L * K);
+        phase = 0;
+        ck = cc = cu = -1;
+        lo = hi = kInf;
     }
+
     bool next(Probe& out) override {
-        if(cursor==l*(1<<k)) return false;
-        out.table=cursor/(1<<k); out.key=cursor%(1<<k); out.score=0;
-        for(int j=0;j<k;++j) {
-            double z=projection[out.table*k+j];
-            if(((out.key>>(k-1-j))&1)!=(z>0)) out.score+=z*z;
+        if (phase == 2) {
+            while (cursor == batch.size())
+                if (!refill()) return false;
+            const Item& it = batch[cursor++];
+            out.table = (int)it.table;
+            out.key = (int)it.key;
+            out.score = it.score;
+            return true;
+        }
+        if (phase == 0) start();
+        if (heap.empty()) return false;
+        if (emitted >= kHeapProbes && heap[0].score > last_score) {
+            switch_to_batches();
+            return next(out);
+        }
+        pop_heap(out);
+        return true;
+    }
+
+    bool stop(const SearchState& s) override {
+        if (s.result_count < s.requested_k || !(s.kth_score > 0)) return false;
+        if (s.kth_score != ck || s.maximum_inner_product != cu || s.approximation_ratio != cc)
+            refresh(s);
+        const double d = s.next_score;
+        if (d >= hi) return true;
+        if (d < lo) return false;
+        return exact(d);
+    }
+
+private:
+    // Shift/expand frontier node: subset S of sorted flip indices with
+    // largest index `last`; low/high are the half sums of S without `last`.
+    struct Node {
+        double score, low, high;
+        uint32_t bits;
+        uint16_t table;
+        int16_t last;
+    };
+    struct Item { double score; uint32_t table, key; };
+    static bool before(double sa, uint32_t ta, double sb, uint32_t tb) {
+        return sa < sb || (sa == sb && ta < tb);
+    }
+
+    int L = 0, K = 0, h = 0, nx = 0, ny = 0, phase = 0;
+    std::vector<double> proj, w;
+    std::vector<uint32_t> fb, natural;
+    long long emitted = 0;
+    double last_score = 0;
+    std::vector<Node> heap;
+    // batch phase
+    std::vector<double> xs, ys;
+    std::vector<uint32_t> xb, yb;
+    std::vector<int> rowpos, rowend;
+    std::vector<Item> batch, tmp;
+    std::vector<uint16_t> q1, q2;
+    size_t cursor = 0;
+    long long remaining = 0;
+    double done_to = 0, prev_t = 0, next_t = 0;
+    long long prev_count = 0, done_count = 0;
+    // termination cache
+    Calibration* cal = nullptr;
+    const char* cal_path = nullptr;
+    std::atomic<int>* cut = nullptr;
+    int cut_L = -1;
+    double ck = -1, cc = -1, cu = -1;
+    double lo = kInf, hi = kInf;
+    int row = -1, need = 0;
+
+    double node_score(double low, double high, int m, const double* W) const {
+        return m < h ? low + W[m] : low + (high + W[m]);
+    }
+
+    void start() {
+        phase = 1;
+        h = K / 2;
+        w.resize((size_t)L * K);
+        fb.resize((size_t)L * K);
+        natural.resize(L);
+        heap.clear();
+        heap.reserve(kHeapProbes + L + 8);
+        for (int t = 0; t < L; ++t) {
+            double* W = &w[(size_t)t * K];
+            uint32_t* B = &fb[(size_t)t * K];
+            const double* p = &proj[(size_t)t * K];
+            uint32_t key = 0;
+            for (int j = 0; j < K; ++j) {
+                const double z = p[j];
+                key = (key << 1) | (z > 0 ? 1u : 0u);
+                const double v = z * z;
+                const uint32_t bit = 1u << (K - 1 - j);
+                int q = j;
+                while (q > 0 && W[q - 1] > v) { W[q] = W[q - 1]; B[q] = B[q - 1]; --q; }
+                W[q] = v; B[q] = bit;
+            }
+            natural[t] = key;
+            Node root = {0.0, 0.0, 0.0, 0u, (uint16_t)t, -1};
+            heap.push_back(root);   // equal scores in table order form a heap
+        }
+        emitted = 0;
+        last_score = 0;
+        remaining = (long long)L << K;
+    }
+
+    void sift_down(Node v) {
+        Node* a = heap.data();
+        const size_t n = heap.size();
+        size_t pos = 0;
+        for (;;) {
+            size_t c = 2 * pos + 1;
+            if (c >= n) break;
+            if (c + 1 < n && before(a[c + 1].score, a[c + 1].table, a[c].score, a[c].table)) ++c;
+            if (!before(a[c].score, a[c].table, v.score, v.table)) break;
+            a[pos] = a[c];
+            pos = c;
         }
-        ++cursor; return true;
+        a[pos] = v;
+    }
+    void sift_up(Node v) {
+        size_t pos = heap.size();
+        heap.push_back(v);
+        Node* a = heap.data();
+        while (pos > 0) {
+            size_t p = (pos - 1) >> 1;
+            if (!before(v.score, v.table, a[p].score, a[p].table)) break;
+            a[pos] = a[p];
+            pos = p;
+        }
+        a[pos] = v;
+    }
+
+    void pop_heap(Probe& out) {
+        const Node top = heap[0];
+        const int t = top.table;
+        out.table = t;
+        out.key = (int)(natural[t] ^ top.bits);
+        out.score = top.score;
+        ++emitted;
+        --remaining;
+        last_score = top.score;
+        const int m = top.last + 1;
+        if (m < K) {
+            const double* W = &w[(size_t)t * K];
+            const uint32_t* B = &fb[(size_t)t * K];
+            double low = top.low, high = top.high;
+            if (top.last >= 0) {
+                // shift: replace `last` by m; the subset without its last is unchanged
+                Node shift = {node_score(low, high, m, W), low, high,
+                              top.bits ^ B[top.last] ^ B[m], top.table, (int16_t)m};
+                if (top.last < h) low = low + W[top.last]; else high = high + W[top.last];
+                Node grow = {node_score(low, high, m, W), low, high, top.bits | B[m], top.table, (int16_t)m};
+                sift_down(shift);
+                sift_up(grow);
+            } else {
+                Node grow = {node_score(low, high, m, W), low, high, top.bits | B[m], top.table, (int16_t)m};
+                sift_down(grow);
+            }
+        } else {
+            Node v = heap.back();
+            heap.pop_back();
+            if (!heap.empty()) sift_down(v);
+        }
+    }
+
+    // Sorted subset sums of n ascending costs, each summed in index order.
+    static void subset_sums(const double* c, const uint32_t* b, int n, double* s, uint32_t* sb,
+                            double* ts, uint32_t* tb) {
+        s[0] = 0; sb[0] = 0;
+        int len = 1;
+        for (int e = 0; e < n; ++e) {
+            const double add = c[e];
+            const uint32_t bit = b[e];
+            int p = 0, q = 0, o = 0;
+            while (p < len && q < len) {
+                const double sp = s[p], sq = s[q] + add;
+                const bool keep = sp <= sq;
+                ts[o] = keep ? sp : sq;
+                tb[o] = keep ? sb[p] : (sb[q] | bit);
+                p += keep;
+                q += !keep;
+                ++o;
+            }
+            while (p < len) { ts[o] = s[p]; tb[o++] = sb[p++]; }
+            while (q < len) { ts[o] = s[q] + add; tb[o++] = sb[q++] | bit; }
+            len <<= 1;
+            std::memcpy(s, ts, sizeof(double) * len);
+            std::memcpy(sb, tb, sizeof(uint32_t) * len);
+        }
+    }
+
+    void switch_to_batches() {
+        phase = 2;
+        nx = 1 << h;
+        ny = 1 << (K - h);
+        xs.resize((size_t)L * nx); xb.resize((size_t)L * nx);
+        ys.resize((size_t)L * ny); yb.resize((size_t)L * ny);
+        rowpos.assign((size_t)L * nx, 0);
+        rowend.assign(L, 1);
+        std::vector<double> ts((size_t)(nx > ny ? nx : ny));
+        std::vector<uint32_t> tb(ts.size());
+        for (int t = 0; t < L; ++t) {
+            const double* W = &w[(size_t)t * K];
+            const uint32_t* B = &fb[(size_t)t * K];
+            subset_sums(W, B, h, &xs[(size_t)t * nx], &xb[(size_t)t * nx], ts.data(), tb.data());
+            subset_sums(W + h, B + h, K - h, &ys[(size_t)t * ny], &yb[(size_t)t * ny], ts.data(), tb.data());
+        }
+        // Everything scoring <= last_score has been emitted by the heap.
+        done_to = last_score;
+        done_count = emitted;
+        prev_t = last_score;
+        prev_count = emitted;
+        next_t = last_score > 0 ? last_score * 1.5 : 1.0;
+        batch.clear();
+        cursor = 0;
+    }
+
+    // Emits the next batch: every bucket scoring in (done_to, T].
+    bool refill() {
+        if (remaining == 0) return false;
+        for (;;) {
+            const double T = next_t;
+            batch.clear();
+            cursor = 0;
+            for (int t = 0; t < L; ++t) {
+                const double* X = &xs[(size_t)t * nx];
+                const double* Y = &ys[(size_t)t * ny];
+                const uint32_t* XB = &xb[(size_t)t * nx];
+                const uint32_t* YB = &yb[(size_t)t * ny];
+                int* pos = &rowpos[(size_t)t * nx];
+                const uint32_t nat = natural[t];
+                int end = rowend[t];
+                while (end < nx && X[end] <= T) ++end;
+                rowend[t] = end;
+                for (int i = 0; i < end; ++i) {
+                    int j = pos[i];
+                    if (j == ny) continue;
+                    const double xv = X[i];
+                    while (j < ny && xv + Y[j] <= done_to) ++j;
+                    const uint32_t xk = nat ^ XB[i];
+                    double s;
+                    while (j < ny && (s = xv + Y[j]) <= T) {
+                        Item it = {s, (uint32_t)t, xk ^ YB[j]};
+                        batch.push_back(it);
+                        ++j;
+                    }
+                    pos[i] = j;
+                }
+            }
+            const double from = done_to;
+            done_to = T;
+            const long long count = done_count + (long long)batch.size();
+            // Aim for doubling the emitted total with each batch.
+            double factor = 2.0;
+            if (count > prev_count && prev_count > 0 && T > prev_t && prev_t > 0) {
+                const double alpha = std::log((double)count / prev_count) / std::log(T / prev_t);
+                if (alpha > 0) factor = std::pow(2.0, 1.0 / alpha);
+            }
+            if (factor < 1.1) factor = 1.1;
+            if (factor > 4.0) factor = 4.0;
+            prev_t = T;
+            prev_count = count;
+            done_count = count;
+            next_t = T > 0 ? T * factor : 1.0;
+            if (count >= ((long long)L << K)) next_t = kInf;
+            if (!batch.empty()) {
+                sort_batch(from);
+                remaining -= (long long)batch.size();
+                return true;
+            }
+            if (T == kInf) return false;
+        }
+    }
+
+    static void insertion(std::vector<Item>& v) {
+        for (size_t a = 1; a < v.size(); ++a) {
+            if (!before(v[a].score, v[a].table, v[a - 1].score, v[a - 1].table)) continue;
+            Item x = v[a];
+            size_t b = a;
+            while (b > 0 && before(x.score, x.table, v[b - 1].score, v[b - 1].table)) { v[b] = v[b - 1]; --b; }
+            v[b] = x;
+        }
+    }
+
+    // Stable LSD radix sort on a monotone 16-bit quantization of the score,
+    // then an insertion pass that only reorders items sharing a quantum.
+    void sort_batch(double from) {
+        const size_t n = batch.size();
+        if (n < 2) return;
+        double top = from;
+        for (size_t a = 0; a < n; ++a) top = batch[a].score > top ? batch[a].score : top;
+        if (n <= 48 || !(top > from)) { insertion(batch); return; }
+        const double scale = 65535.0 / (top - from);
+        tmp.resize(n); q1.resize(n); q2.resize(n);
+        uint32_t c0[257], c1[257];
+        std::memset(c0, 0, sizeof(c0));
+        std::memset(c1, 0, sizeof(c1));
+        for (size_t a = 0; a < n; ++a) {
+            const double v = (batch[a].score - from) * scale;
+            const uint16_t q = v <= 0 ? 0 : (v >= 65535.0 ? 65535 : (uint16_t)v);
+            q1[a] = q;
+            ++c0[(q & 255) + 1];
+            ++c1[(q >> 8) + 1];
+        }
+        for (int r = 0; r < 256; ++r) { c0[r + 1] += c0[r]; c1[r + 1] += c1[r]; }
+        for (size_t a = 0; a < n; ++a) { const uint32_t d = c0[q1[a] & 255]++; tmp[d] = batch[a]; q2[d] = q1[a]; }
+        for (size_t a = 0; a < n; ++a) { const uint32_t d = c1[q2[a] >> 8]++; batch[d] = tmp[a]; }
+        insertion(batch);
+    }
+
+    void refresh(const SearchState& s) {
+        ck = s.kth_score; cc = s.approximation_ratio; cu = s.maximum_inner_product;
+        const double bound = cc * cu;
+        if (ck >= bound) { lo = hi = -kInf; return; }
+        if (cal_path != s.calibration_path || !cal) {
+            cal_path = s.calibration_path;
+            cal = cal_path ? calibration(cal_path) : nullptr;
+            cut = nullptr;
+        }
+        if (!cal || !cal->ok) { lo = hi = kInf; return; }
+        if (!cut || cut_L != s.hash_tables) { cut_L = s.hash_tables; cut = cal->cutoffs_for(cut_L); }
+        const double theta = std::acos(ck / bound);
+        const double rr = std::ceil(theta / cal->theta_step);
+        const int r = rr >= cal->rows - 1 ? cal->rows - 1 : (rr > 0 ? (int)rr : 0);
+        row = r;
+        need = cal->cutoff(cut, r, cut_L);
+        if (need == -2) { lo = -kInf; hi = kInf; return; }
+        if (need >= cal->cols) { lo = hi = kInf; return; }
+        if (need == 0) { lo = hi = -kInf; return; }
+        const double t = need * cal->score_step;
+        lo = t * (1 - 1e-9);
+        hi = t * (1 + 1e-9);
+    }
+
+    bool exact(double d) const {
+        const double q = std::floor(d / cal->score_step);
+        const int j = q >= cal->cols - 1 ? cal->cols - 1 : (q > 0 ? (int)q : 0);
+        if (need == -2) return rule_holds(cal->at(row, j), cut_L);
+        return j >= need;
     }
-    bool stop(const SearchState&) override { return false; }
 };
+
+}  // namespace
+
 std::unique_ptr<QueryCore> make_query_core() {
-    return std::unique_ptr<QueryCore>(new ExhaustiveCore());
+    return std::unique_ptr<QueryCore>(new FargoCore());
 }
